-- AddCheck (hand-written): home facts stay in range. NULL passes, so a draft can be incomplete.
ALTER TABLE "Property" ADD CONSTRAINT "Property_beds_check" CHECK ("beds" BETWEEN 0 AND 20);
ALTER TABLE "Property" ADD CONSTRAINT "Property_baths_check"
    CHECK ("baths" BETWEEN 0 AND 20 AND "baths" * 2 = floor("baths" * 2));
ALTER TABLE "Property" ADD CONSTRAINT "Property_sqft_check" CHECK ("sqft" BETWEEN 100 AND 20000);
ALTER TABLE "Property" ADD CONSTRAINT "Property_lotSqft_check" CHECK ("lotSqft" > 0);
ALTER TABLE "Property" ADD CONSTRAINT "Property_yearBuilt_check"
    CHECK ("yearBuilt" BETWEEN 1800 AND EXTRACT(YEAR FROM CURRENT_DATE));
ALTER TABLE "Property" ADD CONSTRAINT "Property_repairEstimate_check" CHECK ("repairEstimate" >= 0);

-- AddCheck (hand-written): units only for a multi-family home, 2 to 500.
ALTER TABLE "Property" ADD CONSTRAINT "Property_units_check"
    CHECK ("units" IS NULL OR ("propertyType" = 'MULTI_FAMILY' AND "units" BETWEEN 2 AND 500));

-- AddCheck (hand-written): a positive minimum price no higher than the maximum.
ALTER TABLE "ListingPackage" ADD CONSTRAINT "ListingPackage_price_check"
    CHECK ("priceExpectationMin" > 0 AND "priceExpectationMin" <= "priceExpectationMax");

-- AddCheck (hand-written): JPEG, PNG, or WebP; 1 byte to 10 MB; position 0-19 (at most 20 photos).
ALTER TABLE "Photo" ADD CONSTRAINT "Photo_contentType_check"
    CHECK ("contentType" IN ('image/jpeg', 'image/png', 'image/webp'));
ALTER TABLE "Photo" ADD CONSTRAINT "Photo_sizeBytes_check" CHECK ("sizeBytes" BETWEEN 1 AND 10485760);
ALTER TABLE "Photo" ADD CONSTRAINT "Photo_position_check" CHECK ("position" BETWEEN 0 AND 19);
